WHERE EXISTS (SELECT 1 FROM usuarios WHERE id_rol=1) AND NOT EXISTS
(SELECT 1 FROM versiones_firmware WHERE version='1.1.11' AND chip='ESP32' AND tipo_dispositivo='riego');
UPDATE versiones_firmware SET
descripcion='Las credenciales WiFi/MQTT, asignacion y alturas del tanque enviadas desde la app se verifican en NVS (se relee cada clave) antes de responder YAKU_PROVISIONING_OK; si la escritura falla se responde error en vez de perderlas al reiniciar. Conserva buffer serie, NTP, seguridad sin conexion y watchdog de 1.1.10.',
